  @Nested
  @DisplayName("runSeeds")
  class Seeds {

    private MigrationSeed seed(String id, int order, Runnable action) {
      return new MigrationSeed() {
        @Override
        public String id() {
          return id;
        }

        @Override
        public int order() {
          return order;
        }

        @Override
        public void run() {
          action.run();
        }
      };
    }

    @Test
    @DisplayName("Should run pending seeds in order, skip done ones and record failures")
    void shouldRunSeeds() throws SQLException {
      db.logRow("done", "seed", null);
      db.logRow("retry", "seed", "previous failure");
      List<String> ran = new ArrayList<>();
      Migrations migrations = new Migrations(db.connection("H2"), INDEX, GROUP);

      Map<String, Object> result =
          migrations.runSeeds(List.of(seed("second", 2, () -> ran.add("second")),
              seed("done", 0, () -> ran.add("done")), seed("retry", 1, () -> ran.add("retry")),
              seed("broken", 3, () -> {
                throw new IllegalStateException("no data");
              })), "seeds");

      assertEquals(List.of("retry", "second"), ran);
      assertEquals(List.of("Seed broken failed: no data"), list(result, "errors"));
      assertEquals(List.of("Seed completed: retry", "Seed completed: second"),
          list(result, "queries"));
      assertEquals(1, db.updates(OK_UPDATE));
      assertEquals(1, db.updates(FAIL_INSERT));
    }

    @Test
    @DisplayName("Should keep going when a seed failure cannot be recorded")
    void shouldTolerateUnrecordableFailures() throws SQLException {
      Migrations migrations = new Migrations(db.connection("H2"), INDEX, GROUP);
      db.failWith = sql -> sql.contains(FAIL_INSERT);
      db.failure = new SQLException("log down");

      Map<String, Object> result = migrations.runSeeds(List.of(seed("broken", 0, () -> {
        throw new IllegalStateException("no data");
      })), "seeds");

      assertEquals(List.of("Seed broken failed: no data"), list(result, "errors"));
    }

    @Test
    @DisplayName("Should report errors reading the executed seeds")
    void shouldReportReadErrors() throws SQLException {
      Migrations migrations = new Migrations(db.connection("H2"), INDEX, GROUP);
      db.failWith = sql -> sql.startsWith("CREATE TABLE IF NOT EXISTS _migrations ");
      db.failure = new SQLException("no table");

      assertEquals(List.of("no table"), list(migrations.runSeeds(List.of(), "seeds"), "errors"));
    }

    @Test
    @DisplayName("Should not run while another instance holds the lock")
    void shouldRespectLock() throws SQLException {
      db.lock(true, Instant.now());
      Migrations migrations = new Migrations(db.connection("H2"), INDEX, GROUP);

      assertEquals(List.of("The seeds are locked."),
          list(migrations.runSeeds(List.of(), "seeds"), "errors"));
    }
  }

  /**
   * A JDBC double that records every statement and keeps the migrations log and lock rows.
   */
  static class FakeDb {
    final List<String> executed = new ArrayList<>();
    final List<Map<String, String>> log = new ArrayList<>();
    Connection connection;
    boolean lockRowPresent = true;
    boolean locked;
    Instant granted;
    Predicate<String> failWith = _ -> false;
    Exception failure;

    void logRow(String filename, String md5, String error) {
      Map<String, String> row = new HashMap<>();
      row.put("filename", filename);
      row.put("md5sum", md5);
      row.put("error", error);
      log.add(row);
    }

    void lock(boolean locked, Instant granted) {
      this.locked = locked;
      this.granted = granted;
    }

    long updates(String fragment) {
      return executed.stream().filter(sql -> sql.contains(fragment)).count();
    }

    Connection connection(String driver) throws SQLException {
      connection = mock(Connection.class);
      DatabaseMetaData meta = mock(DatabaseMetaData.class);
      when(meta.getDriverName()).thenReturn(driver);
      when(connection.getMetaData()).thenReturn(meta);
      when(connection.prepareStatement(anyString()))
          .thenAnswer(inv -> statement(inv.getArgument(0)));
      return connection;
    }

    private PreparedStatement statement(String sql) throws SQLException {
      PreparedStatement ps = mock(PreparedStatement.class);
      when(ps.execute()).thenAnswer(_ -> run(sql));
      when(ps.executeUpdate()).thenAnswer(_ -> {
        run(sql);
        return 1;
      });
      doAnswer(_ -> null).when(ps).setString(anyInt(), anyString());
      when(ps.executeQuery()).thenAnswer(_ -> {
        run(sql);
        return sql.contains("SELECT locked") ? lockRows() : logRows();
      });
      return ps;
    }

    private boolean run(String sql) throws Exception {
      if (failWith.test(sql)) {
        throw failure;
      }
      executed.add(sql.trim());
      return true;
    }

    private ResultSet logRows() throws SQLException {
      Iterator<Map<String, String>> rows = new ArrayList<>(log).iterator();
      ResultSet rs = mock(ResultSet.class);
      Map<String, String>[] current = new Map[1];
      when(rs.next()).thenAnswer(_ -> {
        if (rows.hasNext()) {
          current[0] = rows.next();
          return true;
        }
        return false;
      });
      when(rs.getString(anyString())).thenAnswer(inv -> current[0].get(inv.<String>getArgument(0)));
      return rs;
    }

    private ResultSet lockRows() throws SQLException {
      ResultSet rs = mock(ResultSet.class);
      when(rs.next()).thenReturn(lockRowPresent);
      when(rs.getBoolean("locked")).thenReturn(locked);
      when(rs.getInt("locked")).thenReturn(locked ? 1 : 0);
      when(rs.getTimestamp("granted")).thenReturn(null == granted ? null : Timestamp.from(granted));
      return rs;
    }
  }
